import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, MAX_ATTEMPTS, type JobRow } from './db.ts';

const db = openDatabase();
let stopping = false;
let wake: (() => void) | null = null;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
    wake?.();
  });
}

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const POLL_MS = 200;

const now = () => new Date().toISOString();

const beatStmt = db.prepare('INSERT INTO heartbeat (id, at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET at = excluded.at');
function beat(): void {
  try {
    beatStmt.run(Date.now());
  } catch (err) {
    console.error('heartbeat failed', err);
  }
}
beat();
const beatTimer = setInterval(beat, 1000);

// Recover jobs that were running when a previous worker died: redo the interrupted attempt.
db.prepare(
  `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_after = 0, updated_at = ?
   WHERE status = 'running'`,
).run(now());

const pickStmt = db.prepare(
  `SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq ASC LIMIT 1`,
);
const claimStmt = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress = 0, updated_at = ?
   WHERE id = ? AND status = 'queued'`,
);
const getStmt = db.prepare('SELECT * FROM jobs WHERE id = ?');
const progressStmt = db.prepare(`UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ? AND status = 'running'`);
const completeStmt = db.prepare(
  `UPDATE jobs SET status = 'completed', progress = steps, output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const retryStmt = db.prepare(
  `UPDATE jobs SET status = 'queued', progress = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const failStmt = db.prepare(
  `UPDATE jobs SET status = 'failed', progress = 0, output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'`,
);
const requeueStmt = db.prepare(
  `UPDATE jobs SET status = 'queued', attempts = MAX(attempts - 1, 0), progress = 0, run_after = 0, updated_at = ?
   WHERE id = ? AND status = 'running'`,
);

async function processJob(job: JobRow): Promise<void> {
  const claimed = claimStmt.run(now(), job.id);
  if (claimed.changes !== 1) return;
  const row = getStmt.get(job.id) as unknown as JobRow;
  const attempt = row.attempts;

  if (attempt <= row.fail_attempts) {
    await sleep(STEP_MS);
    if (attempt >= MAX_ATTEMPTS) {
      failStmt.run('transient failure', now(), row.id);
    } else {
      retryStmt.run(Date.now() + RETRY_DELAY_MS, now(), row.id);
    }
    return;
  }

  for (let i = 1; i <= row.steps; i++) {
    await sleep(STEP_MS);
    if (stopping) {
      requeueStmt.run(now(), row.id);
      return;
    }
    if (i < row.steps) progressStmt.run(i, now(), row.id);
  }
  completeStmt.run(row.input.toUpperCase(), now(), row.id);
}

console.log('worker started');
while (!stopping) {
  let job: JobRow | undefined;
  try {
    job = pickStmt.get(Date.now()) as unknown as JobRow | undefined;
    if (job) await processJob(job);
  } catch (err) {
    console.error('worker error', err);
  }
  if (!job && !stopping) {
    await new Promise<void>((resolve) => {
      const t = setTimeout(resolve, POLL_MS);
      wake = () => {
        clearTimeout(t);
        resolve();
      };
    });
    wake = null;
  }
}
clearInterval(beatTimer);
try {
  db.prepare('UPDATE heartbeat SET at = 0 WHERE id = 1').run();
} catch {}
db.close();
console.log('worker stopped');
EOF

cat > src/server.ts <<'EOF'
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY = 1024 * 1024;
const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

interface FieldError {
  field: string;
  message: string;
}

class HttpError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
    public fields?: FieldError[],
  ) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  const data = JSON.stringify(body);
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'cache-control': 'no-store',
    'content-length': Buffer.byteLength(data),
    ...headers,
  });
  res.end(data);
}

function sendError(res: ServerResponse, err: HttpError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields) error.fields = err.fields;
  else if (err.code === 'invalid_request') error.fields = [];
  send(res, err.status, { error }, err.status === 405 ? { allow: (err as HttpError & { allow?: string }).allow ?? '' } : {});
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooBig = false;
    req.on('data', (c: Buffer) => {
      size += c.length;
      if (size > MAX_BODY) tooBig = true;
      else chunks.push(c);
    });
    req.on('end', () => resolve(tooBig ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

const insertStmt = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, created_at, updated_at, run_after, idem_key, idem_payload)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, 0, ?, ?)`,
);
const byIdStmt = db.prepare('SELECT * FROM jobs WHERE id = ?');
const byKeyStmt = db.prepare('SELECT * FROM jobs WHERE idem_key = ?');
const listStmt = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const heartbeatStmt = db.prepare('SELECT at FROM heartbeat WHERE id = 1');

function isIntIn(v: unknown, min: number, max: number): boolean {
  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];
  const rawKey = req.headers['idempotency-key'];
  let key: string | null = null;
  if (rawKey !== undefined) {
    const k = Array.isArray(rawKey) ? rawKey.join(',') : rawKey;
    if (!KEY_RE.test(k)) fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
    else key = k;
  }

  const raw = await readBody(req);
  const ctype = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  let body: unknown = undefined;
  let bodyOk = false;
  if (ctype !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (raw === null) {
    fields.push({ field: 'body', message: 'body is too large' });
  } else {
    try {
      body = JSON.parse(raw);
      if (typeof body !== 'object' || body === null || Array.isArray(body)) {
        fields.push({ field: 'body', message: 'body must be a JSON object' });
      } else bodyOk = true;
    } catch {
      fields.push({ field: 'body', message: 'body must be valid JSON' });
    }
  }

  let input = '';
  let steps = 5;
  let failAttempts = 0;
  if (bodyOk) {
    const obj = body as Record<string, unknown>;
    for (const k of Object.keys(obj)) {
      if (k !== 'input' && k !== 'steps' && k !== 'failAttempts') fields.push({ field: k, message: 'unknown field' });
    }
    if (!Object.hasOwn(obj, 'input')) fields.push({ field: 'input', message: 'input is required' });
    else if (typeof obj.input !== 'string') fields.push({ field: 'input', message: 'input must be a string' });
    else if (obj.input.length < 1 || obj.input.length > 1000)
      fields.push({ field: 'input', message: 'input must be 1-1000 characters' });
    else if (obj.input.trim() === '') fields.push({ field: 'input', message: 'input must not be only whitespace' });
    else input = obj.input;
    if (Object.hasOwn(obj, 'steps')) {
      if (!isIntIn(obj.steps, 1, 20)) fields.push({ field: 'steps', message: 'steps must be an integer from 1 to 20' });
      else steps = obj.steps as number;
    }
    if (Object.hasOwn(obj, 'failAttempts')) {
      if (!isIntIn(obj.failAttempts, 0, 5))
        fields.push({ field: 'failAttempts', message: 'failAttempts must be an integer from 0 to 5' });
      else failAttempts = obj.failAttempts as number;
    }
  }
  if (fields.length > 0) throw new HttpError(400, 'invalid_request', 'The request is invalid.', fields);

  const payload = JSON.stringify({ input, steps, failAttempts });
  const ts = new Date().toISOString();
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== null) {
      const existing = byKeyStmt.get(key) as (JobRow & { idem_payload: string }) | undefined;
      if (existing) {
        db.exec('COMMIT');
        if (existing.idem_payload === payload) return send(res, 200, toJob(existing));
        throw new HttpError(409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.');
      }
    }
    const id = randomUUID();
    insertStmt.run(id, input, steps, failAttempts, ts, ts, key, key !== null ? payload : null);
    const row = byIdStmt.get(id) as unknown as JobRow;
    db.exec('COMMIT');
    send(res, 201, toJob(row));
  } catch (err) {
    if (db.isTransaction) db.exec('ROLLBACK');
    throw err;
  }
}

function methodNotAllowed(allow: string): HttpError {
  const e = new HttpError(405, 'method_not_allowed', 'Method not allowed.') as HttpError & { allow?: string };
  e.allow = allow;
  return e;
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/') {
    if (method !== 'GET' && method !== 'HEAD') throw methodNotAllowed('GET, HEAD');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
    res.end(method === 'HEAD' ? undefined : uiHtml);
    return;
  }
  if (pathname === '/health') {
    if (method !== 'GET') throw methodNotAllowed('GET');
    const row = heartbeatStmt.get() as { at: number } | undefined;
    const up = !!row && Date.now() - row.at <= 3000;
    return send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') {
      const rows = listStmt.all() as unknown as JobRow[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    if (method === 'POST') return createJob(req, res);
    throw methodNotAllowed('GET, POST');
  }
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    if (method !== 'GET') throw methodNotAllowed('GET');
    let id: string;
    try {
      id = decodeURIComponent(m[1]!);
    } catch {
      throw new HttpError(404, 'not_found', 'Job not found.');
    }
    const row = byIdStmt.get(id) as unknown as JobRow | undefined;
    if (!row) throw new HttpError(404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  throw new HttpError(404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT || 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err) => {
    if (res.headersSent) {
      res.destroy();
      return;
    }
    if (err instanceof HttpError) return sendError(res, err);
    console.error(err);
    sendError(res, new HttpError(500, 'internal_error', 'Internal server error.'));
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    if (shuttingDown) return;
    shuttingDown = true;
    server.close(() => {
      db.close();
      process.exit(0);
    });
    server.closeIdleConnections();
    setTimeout(() => {
      server.closeAllConnections();
    }, 2000).unref();
  });
}
EOF

