    .job .input { font-weight: 600; word-break: break-all; }
    .job .result { grid-column: 1 / -1; word-break: break-all; }
    .status-completed { color: #070; } .status-failed { color: #a00; } .status-running { color: #05a; }
  </style>
</head>
<body>
  <h1>Job tracker</h1>
  <form data-testid="job-form" id="job-form" novalidate>
    <label for="job-input">Input</label>
    <input id="job-input" name="input" data-testid="job-input" type="text" autocomplete="off">
    <label for="job-steps">Steps</label>
    <input id="job-steps" name="steps" data-testid="job-steps" type="number" value="5">
    <label for="job-fail-attempts">Fail attempts</label>
    <input id="job-fail-attempts" name="failAttempts" data-testid="job-fail-attempts" type="number" value="0">
    <button type="submit" data-testid="job-submit">Submit</button>
  </form>
  <div id="form-error" data-testid="form-error" role="alert"></div>
  <ul id="job-list" data-testid="job-list"></ul>
  <script>
    const form = document.getElementById('job-form');
    const errorBox = document.getElementById('form-error');
    const list = document.getElementById('job-list');

    function numeric(value) {
      const v = value.trim();
      if (v === '') return undefined;
      const n = Number(v);
      return Number.isFinite(n) ? n : v;
    }

    function showError(err) {
      errorBox.textContent = '';
      const msg = document.createElement('p');
      msg.textContent = (err && err.message) || 'Request failed.';
      errorBox.appendChild(msg);
      if (err && Array.isArray(err.fields) && err.fields.length) {
        const ul = document.createElement('ul');
        for (const f of err.fields) {
          const li = document.createElement('li');
          li.textContent = f.field + ': ' + f.message;
          ul.appendChild(li);
        }
        errorBox.appendChild(ul);
      }
    }

    form.addEventListener('submit', async (e) => {
      e.preventDefault();
      const payload = { input: form.input.value };
      const steps = numeric(form.steps.value);
      const failAttempts = numeric(form.failAttempts.value);
      if (steps !== undefined) payload.steps = steps;
      if (failAttempts !== undefined) payload.failAttempts = failAttempts;
      try {
        const res = await fetch('/api/jobs', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
        const data = await res.json().catch(() => null);
        if (!res.ok) {
          showError(data && data.error);
          return;
        }
        errorBox.textContent = '';
        form.input.value = '';
        await refresh();
      } catch (err) {
        showError({ message: 'Network error: ' + err.message });
      }
    });

    function cell(item, testid, cls) {
      let el = item.querySelector('[data-testid="' + testid + '"]');
      if (!el) {
        el = document.createElement('span');
        el.dataset.testid = testid;
        el.className = cls;
        item.appendChild(el);
      }
      return el;
    }

    function setText(el, text) { if (el.textContent !== text) el.textContent = text; }

    function render(jobs) {
      const existing = new Map();
      for (const el of list.querySelectorAll('[data-testid="job-item"]')) existing.set(el.dataset.jobId, el);
      let prev = null;
      for (const job of jobs) {
        let item = existing.get(job.id);
        if (!item) {
          item = document.createElement('li');
          item.className = 'job';
          item.dataset.testid = 'job-item';
          item.dataset.jobId = job.id;
        }
        existing.delete(job.id);
        setText(cell(item, 'job-input-text', 'input'), job.input);
        const st = cell(item, 'job-status', 'status');
        setText(st, job.status);
        st.className = 'status status-' + job.status;
        setText(cell(item, 'job-progress', 'progress'), job.progress.completed + '/' + job.progress.total);
        const result = job.status === 'completed' && job.result ? job.result.output
          : job.status === 'failed' ? (job.error || '') : '';
        setText(cell(item, 'job-result', 'result'), result);
        const expectedPos = prev ? prev.nextSibling : list.firstChild;
        if (expectedPos !== item) list.insertBefore(item, expectedPos);
        prev = item;
      }
      for (const el of existing.values()) el.remove();
    }

    let inflight = false;
    async function refresh() {
      if (inflight) return;
      inflight = true;
      try {
        const res = await fetch('/api/jobs', { cache: 'no-store' });
        if (res.ok) render((await res.json()).jobs);
      } catch {} finally { inflight = false; }
    }
    refresh();
    setInterval(refresh, 500);
  </script>
</body>
</html>
